import{_ as t,o,c as n,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Keynote- Getting to Know Ceph - Josh Durgin & Neha Ojha, IBM & Dan van der Ster, Clyso","description":"","frontmatter":{"title":"Keynote- Getting to Know Ceph - Josh Durgin & Neha Ojha, IBM & Dan van der Ster, Clyso","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","分布式存储","开源社区","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Getting_to_Know_Ceph_-_Josh_Durgin_Neha_Ojha_IBM_Dan_van_der_Ster_Clyso.md","filePath":"posts/2025/Keynote_-_Getting_to_Know_Ceph_-_Josh_Durgin_Neha_Ojha_IBM_Dan_van_der_Ster_Clyso.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Keynote_-_Getting_to_Know_Ceph_-_Josh_Durgin_Neha_Ojha_IBM_Dan_van_der_Ster_Clyso.md"};function s(l,e,i,h,p,_){return o(),n("div",null,[...e[0]||(e[0]=[r('<p>会议纪要：Ceph项目介绍与社区发展</p><p><strong>会议时间</strong>: 未知<br><strong>会议地点</strong>: 未知<br><strong>参会人员</strong>:</p><ul><li><strong>Josh Durgin</strong>: Ceph资深开发者，现就职于IBM，加拿大维多利亚。</li><li><strong>Neha Ojha</strong>: IBM工程经理，Ceph核心团队成员，旧金山湾区。</li><li><strong>Dan Van der Ster</strong>: Klyo公司CTO，CERN前Ceph服务经理，温哥华。</li></ul><h4 id="会议主要议题" tabindex="-1">会议主要议题： <a class="header-anchor" href="#会议主要议题" aria-label="Permalink to &quot;会议主要议题：&quot;">​</a></h4><ol><li><strong>Ceph项目的组织结构与社区介绍</strong></li><li><strong>Ceph的核心特性与技术优势</strong></li><li><strong>Ceph的用户群体与社区贡献</strong></li><li><strong>Ceph社区的组织与活动</strong></li><li><strong>Ceph基金会的角色与支持</strong></li></ol><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><p><strong>1. Ceph项目的组织结构与社区介绍</strong></p><ul><li><strong>Josh Durgin</strong> 和 <strong>Neha Ojha</strong> 分别介绍了自己在Ceph项目中的角色和贡献，包括开发和管理工作。</li><li><strong>Dan Van der Ster</strong> 分享了他在CERN的Ceph运营经验，强调了用户反馈对项目发展的重要性。</li></ul><p><strong>2. Ceph的核心特性与技术优势</strong></p><ul><li><strong>Ceph</strong> 是一个开源的分布式存储系统，支持对象存储、块存储和文件系统存储，具有高可用性、可扩展性和强一致性。</li><li><strong>CRUSH算法</strong> 确保了Ceph的无单点故障设计，支持复制和纠删码（erasure coding），用户可以根据性能或成本需求进行选择。</li><li>Ceph支持滚动升级和在线扩展，强调一致性优先于性能，确保数据安全。</li></ul><p><strong>3. Ceph的用户群体与社区贡献</strong></p><ul><li><strong>Ceph</strong> 在全球范围内拥有超过13,000名贡献者，代码库包含超过70万行代码和14.6万次提交。</li><li>Ceph在OpenStack生态系统中占据主导地位，85%的OpenStack集群使用Ceph作为后端存储。</li><li>Ceph的Telemetry数据显示，全球有超过3,000个集群和近2 Exabytes的存储容量在使用Ceph。</li></ul><p><strong>4. Ceph社区的组织与活动</strong></p><ul><li>Ceph社区通过GitHub、邮件列表、Slack等平台进行沟通，定期举办用户与开发者会议（User Dev Meetups）。</li><li>Ceph社区的技术领导团队（CLT）已更名为Ceph Steering Committee，正在进行新的组织调整。</li><li>Ceph基金会支持社区活动、文档、测试基础设施等，推动Ceph项目的发展。</li></ul><p><strong>5. Ceph基金会的角色与支持</strong></p><ul><li>Ceph基金会由多家公司组成，支持Ceph社区的发展，包括技术基础设施、文档、活动组织等。</li><li>Ceph社区通过全球范围的Ceph Days活动进行推广，2024年已经举办了多场活动，包括纽约、印度、伦敦和亚洲等地。</li></ul><h4 id="决定事项与后续行动计划" tabindex="-1">决定事项与后续行动计划： <a class="header-anchor" href="#决定事项与后续行动计划" aria-label="Permalink to &quot;决定事项与后续行动计划：&quot;">​</a></h4><ul><li><strong>继续推动Ceph Days活动</strong>：鼓励全球各地的社区成员组织Ceph Days活动，扩大Ceph的影响力。</li><li><strong>加强社区沟通与协作</strong>：通过GitHub、Slack等平台，提升开发者与用户的互动，解决技术问题。</li><li><strong>支持Ceph基金会的工作</strong>：继续推动Ceph项目的开源发展，吸引更多公司和开发者参与。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议详细介绍了Ceph项目的组织结构、技术优势、用户群体以及社区活动。Ceph作为一个开源的分布式存储系统，凭借其高可用性、可扩展性和强一致性，在全球范围内得到了广泛应用。Ceph社区通过多种渠道进行沟通与协作，Ceph基金会则为项目的持续发展提供了重要支持。未来，Ceph社区将继续推动全球范围内的推广活动，吸引更多用户和开发者参与。</p>',20)])])}const u=t(a,[["render",s]]);export{C as __pageData,u as default};
